<script setup lang="ts">
import {computed,ref,watch} from 'vue';
import * as Tone from 'tone';
import {demoProject,blankProject,generate,mergeScores,INSTRUMENTS,midiName,parsePitch,scoreStats,type Project,type Note,type Instrument,type Role,defaultOrchestration,type ViolinTechnique,type FollowTarget,type FollowMethod,type Difficulty,type DynamicMark,defaultInstrumentSettings,defaultExpression,convertTwoFourToFour,parseChordSequence,chordAt,instrumentActivity,transposeScore,defaultArticulation,measureArticulation,type Articulation} from './music';
import {download,exportMusicXml,validateMusicXmlDurations,saveProject,loadProject,importMusicXml,importMidi,scoreFromParts} from './io';
const project=ref<Project>(demoProject());const active=ref<'overview'|'lead'|'arrange'|'score'>('overview');const selectedBar=ref(0);const message=ref('Demo project loaded. Replace its melody and chords with your own.');const importMode=ref<'melody'|'score'>('melody');const selectedTrack=ref(0);const pending=ref<{name:string;notes:Note[]}[]>([]);const playing=ref(false);const score=computed(()=>project.value.generatedScore??generate(project.value));const sections=computed(()=>[...new Set(project.value.bars.map(b=>b.section))]);const chosenSection=ref('A1');const violinTechniques:ViolinTechnique[]=['arpeggio','pizzicato','pizzicato_arpeggio','double_stop','sustained','block'];const followTargets:FollowTarget[]=['independent','Piano','Violin I','Violin II','Bandoneon I'];const followMethods:FollowMethod[]=['exact','octave','adapt','rhythm'];
function violinSetting(inst:'Violin I'|'Violin II'):ViolinTechnique{return project.value.orchestration?.violin[chosenSection.value]?.[inst]??'arpeggio';}
function setViolinSetting(inst:'Violin I'|'Violin II',event:Event){project.value.orchestration??=defaultOrchestration();project.value.orchestration.violin[chosenSection.value]??={};project.value.orchestration.violin[chosenSection.value][inst]=(event.target as HTMLSelectElement).value as ViolinTechnique;}
function followSetting(inst:'Bandoneon I'|'Bandoneon II'){return project.value.orchestration?.bandoneon[chosenSection.value]?.[inst]??{target:'independent' as FollowTarget,method:'adapt' as FollowMethod};}
function setFollow(inst:'Bandoneon I'|'Bandoneon II',field:'target'|'method',event:Event){project.value.orchestration??=defaultOrchestration();project.value.orchestration.bandoneon[chosenSection.value]??={};project.value.orchestration.bandoneon[chosenSection.value][inst]={...followSetting(inst),[field]:(event.target as HTMLSelectElement).value};}
const roles:Role[]=['melody','harmony','chords','bass','fill','variation','rest'];const profiles=[['traditional','Traditional'],['darienzo',"D’Arienzo"],['disarli','Di Sarli'],['fresedo','Fresedo'],['troilo','Troilo'],['canaro','Canaro'],['pugliese','Pugliese']];
const difficulties:Difficulty[]=['easy','intermediate','advanced'];
const dynamicMarks:DynamicMark[]=['pp','p','mp','mf','f','ff'];
function ensureInstrumentSettings(){project.value.instrumentSettings??=defaultInstrumentSettings();}
function instrumentDifficulty(inst:Instrument):Difficulty{return project.value.instrumentSettings?.[inst]?.difficulty??project.value.difficulty??'intermediate';}
function setInstrumentDifficulty(inst:Instrument,e:Event){ensureInstrumentSettings();project.value.instrumentSettings![inst]??={};project.value.instrumentSettings![inst]!.difficulty=(e.target as HTMLSelectElement).value as Difficulty;}
function instrumentDynamicsOffset(inst:Instrument):number{return project.value.instrumentSettings?.[inst]?.dynamicsOffset??0;}
function setInstrumentDynamicsOffset(inst:Instrument,e:Event){ensureInstrumentSettings();project.value.instrumentSettings![inst]??={};project.value.instrumentSettings![inst]!.dynamicsOffset=Number((e.target as HTMLInputElement).value);}
function instrumentTarget(inst:Instrument):number{return Math.round((project.value.instrumentSettings?.[inst]?.activity??(inst==='Voice'?0:0.9))*100);}
function setInstrumentTarget(inst:Instrument,e:Event){ensureInstrumentSettings();project.value.instrumentSettings![inst]??={};project.value.instrumentSettings![inst]!.activity=Number((e.target as HTMLInputElement).value)/100;}
function toggleExpression(field:'enabled'|'crescendo',e:Event){project.value.expression??=defaultExpression();project.value.expression[field]=(e.target as HTMLInputElement).checked;}
function sectionDynamic():DynamicMark{return project.value.expression?.sections[chosenSection.value]??'mf';}
function setSectionDynamic(e:Event){project.value.expression??=defaultExpression();project.value.expression.sections[chosenSection.value]=(e.target as HTMLSelectElement).value as DynamicMark;}
function convertMeter(){try{project.value=convertTwoFourToFour(project.value);selectedBar.value=0;message.value='Converted paired 2/4 measures to 4/4; onset and durations preserved.';}catch(error){message.value=String(error);}}
function activitySummary(inst:Instrument){return Math.round(instrumentActivity(score.value,inst,project.value.bars.length,project.value.beats)*100);}
const articulationModes:Articulation[]=['auto','marcato_staccato','staccato','legato'];
function barArticulation(inst:Instrument):Articulation{return project.value.articulation?.overrides?.[`${inst}:${selectedBar.value}`]??'auto';}
function setBarArticulation(inst:Instrument,e:Event){project.value.articulation??=defaultArticulation();const key=`${inst}:${selectedBar.value}`;const value=(e.target as HTMLSelectElement).value as Articulation;if(value==='auto')delete project.value.articulation.overrides[key];else project.value.articulation.overrides[key]=value;}
function inferredArticulation(inst:Instrument):string{return measureArticulation(project.value,inst,selectedBar.value)??'not applicable';}
function setTranspose(e:Event){const n=Number((e.target as HTMLInputElement).value);if(Number.isInteger(n)&&n>=-24&&n<=24)project.value.transposeSemitones=n;}
// Song overview: measure-level overrides are sparse and do not replace section defaults.
const overviewInstrument=ref<Instrument>('Violin II');
const overviewStart=ref(1);
const overviewEnd=ref(8);
const overviewRole=ref<'inherit'|Role>('inherit');
const overviewArt=ref<Articulation>('auto');
const overviewTechnique=ref<'inherit'|ViolinTechnique>('inherit');
const overviewNotice=ref('');
const newSongOpen=ref(false);
const newSongTitle=ref('Untitled Tango');
const newSongMeasures=ref(32);
const newSongBeats=ref(4);
const newSongBpm=ref(124);
function createBlankSong(){
  try{
    const fresh=blankProject({title:newSongTitle.value,measures:newSongMeasures.value,beats:newSongBeats.value,bpm:newSongBpm.value});
    if(!window.confirm('Create a new blank song? Unsaved changes to the current project will be lost. Save your .tango project first if needed.'))return;
    if(playing.value){Tone.getTransport().stop();Tone.getTransport().cancel();playing.value=false;}
    project.value=fresh;
    selectedBar.value=0;overviewFocus.value=0;overviewStart.value=1;overviewEnd.value=Math.min(8,fresh.bars.length);
    overviewInstrument.value='Violin II';chosenSection.value='A1';active.value='lead';
    chordEditorOpen.value=false;pending.value=[];newSongOpen.value=false;
    message.value=`Created ${fresh.bars.length} empty measures. Enter chords and melody, then generate the orchestra.`;
  }catch(error){message.value=`Cannot create blank song: ${String(error)}`;}
}
const chordEditorOpen=ref(false);
const chordDraft=ref('');
function openChordEditor(i:number){
  if(i<0||i>=project.value.bars.length)return;
  selectedBar.value=i;overviewFocus.value=i;
  chordDraft.value=project.value.bars[i].chord;
  chordEditorOpen.value=true;
}
function applyChordEditor(){
  try{
    const events=parseChordSequence(chordDraft.value,project.value.beats);
    const normalized=events.map(e=>e.chord).join(',');
    project.value.bars[selectedBar.value].chord=normalized;
    project.value.generatedScore=undefined;
    message.value=normalized?`Measure ${selectedBar.value+1}: ${normalized}. Arrangement regenerated for preview; export uses the new harmony.`:`Measure ${selectedBar.value+1}: harmony cleared.`;
    overviewNotice.value=message.value;
    chordEditorOpen.value=false;
  }catch(error){message.value=`Chord entry rejected: ${String(error)}`;overviewNotice.value=message.value;}
}
function chordBeatLabels(chord:string):string{
  try{return chord.trim()?Array.from({length:project.value.beats},(_,beat)=>chordAt(chord,project.value.beats,beat)).join(' · '):'No harmony yet';}catch{return 'Invalid harmony';}
}

const overviewFocus=ref(0);
const overviewInstruments=computed(()=>INSTRUMENTS.filter(inst=>inst!=='Voice'||project.value.roles[project.value.bars[0]?.section]?.Voice!=='rest'));
function effectiveRole(inst:Instrument,i:number):Role{return project.value.measureRoles?.[`${inst}:${i}`]??project.value.roles[project.value.bars[i]?.section]?.[inst]??'rest';}
function roleOverridden(inst:Instrument,i:number){return Object.prototype.hasOwnProperty.call(project.value.measureRoles??{},`${inst}:${i}`);}
function violinTechnique(inst:Instrument,i:number):ViolinTechnique|undefined{return inst.startsWith('Violin')?(project.value.measureViolinTechniques?.[`${inst}:${i}`]??project.value.orchestration?.violin?.[project.value.bars[i].section]?.[inst as 'Violin I'|'Violin II']??'arpeggio'):undefined;}
function articulationOverride(inst:Instrument,i:number):Articulation{return project.value.articulation?.overrides?.[`${inst}:${i}`]??'auto';}
function cellArticulation(inst:Instrument,i:number):string{const mode=measureArticulation(project.value,inst,i);return mode==='marcato_staccato'?'Marc.':mode==='staccato'?'Stacc.':mode==='legato'?(inst.startsWith('Violin')?'Arco':'Legato'):'—';}
function cellLabel(inst:Instrument,i:number):string{const role=effectiveRole(inst,i);const tech=violinTechnique(inst,i);return role==='chords'&&tech?tech.replaceAll('_',' '):role;}
function focusOverview(inst:Instrument,i:number){overviewInstrument.value=inst;overviewFocus.value=i;overviewStart.value=i+1;overviewEnd.value=i+1;selectedBar.value=i;chosenSection.value=project.value.bars[i].section;overviewRole.value=project.value.measureRoles?.[`${inst}:${i}`]??'inherit';overviewArt.value=articulationOverride(inst,i);overviewTechnique.value=project.value.measureViolinTechniques?.[`${inst}:${i}`]??'inherit';}
function applyOverviewRange(){const start=Math.max(0,Math.min(project.value.bars.length-1,Math.floor(overviewStart.value)-1)),end=Math.max(start,Math.min(project.value.bars.length-1,Math.floor(overviewEnd.value)-1));if(!Number.isFinite(start)||!Number.isFinite(end)){overviewNotice.value='Invalid measure range';return;}project.value.measureRoles??={};project.value.measureViolinTechniques??={};project.value.articulation??=defaultArticulation();for(let i=start;i<=end;i++){const key=`${overviewInstrument.value}:${i}`;if(overviewRole.value==='inherit')delete project.value.measureRoles[key];else project.value.measureRoles[key]=overviewRole.value;if(overviewArt.value==='auto')delete project.value.articulation.overrides[key];else if(overviewInstrument.value.startsWith('Violin')||overviewInstrument.value.startsWith('Bandoneon'))project.value.articulation.overrides[key]=overviewArt.value;if(overviewInstrument.value.startsWith('Violin')){if(overviewTechnique.value==='inherit')delete project.value.measureViolinTechniques[key];else project.value.measureViolinTechniques[key]=overviewTechnique.value;}}
project.value.generatedScore=undefined;overviewNotice.value=`Applied settings to ${overviewInstrument.value}, measures ${start+1}–${end+1}. The preview now uses regenerated notes; protected imported measures are unchanged when using Generate orchestra.`;selectedBar.value=start;}
function applyOverviewSection(){const index=project.value.bars.findIndex(b=>b.section===chosenSection.value);const positions=project.value.bars.map((b,i)=>b.section===chosenSection.value?i:-1).filter(i=>i>=0);if(index<0||!positions.length)return;const begin=Math.min(...positions),finish=Math.max(...positions);if(positions.length!==finish-begin+1){overviewNotice.value='Section is non-contiguous. Select a measure range instead.';return;}overviewStart.value=begin+1;overviewEnd.value=finish+1;applyOverviewRange();}
const bar=computed(()=>project.value.bars[selectedBar.value]);const melodyString=computed(()=>bar.value.melody.map(n=>`${midiName(n.pitch)}:${n.duration}@${n.start}`).join(' '));const melodyText=ref('');watch(selectedBar,()=>melodyText.value=melodyString.value,{immediate:true});watch(()=>project.value.bars[selectedBar.value]?.melody,()=>melodyText.value=melodyString.value,{deep:true});
function setMelody(){const notes:Note[]=[];const tokens=melodyText.value.trim().split(/\s+/).filter(Boolean);let next=0;for(const token of tokens){const m=token.match(/^([A-Ga-g][#b]?-?\d+)(?::([\d.]+))?(?:@([\d.]+))?$/);if(!m){message.value=`Invalid note: ${token}. Example: D5:1@0`;return;}const pitch=parsePitch(m[1]);if(pitch===null)continue;const duration=Number(m[2]??1),start=m[3]===undefined?next:Number(m[3]);if(!Number.isFinite(duration)||duration<=0||start<0||start+duration>project.value.beats+0.00001){message.value=`Invalid timing: ${token}`;return;}notes.push({pitch,start,duration});next=start+duration;}bar.value.melody=notes;message.value=`Updated melody in bar ${selectedBar.value+1}. Regenerate to apply.`;}
function regenerate(){const fresh=generate(project.value);project.value.generatedScore=mergeScores(project.value,fresh);message.value=`Generated ${scoreStats(project.value.generatedScore)} notes across ${INSTRUMENTS.length} parts. Protected measures retained.`;}
function setRole(inst:Instrument,e:Event){const sec=chosenSection.value;project.value.roles[sec]??={};project.value.roles[sec][inst]=(e.target as HTMLSelectElement).value as Role;}
function setProtected(inst:Instrument,b:number,v:boolean){project.value.protectedBars[`${inst}:${b}`]=v;}
function exportXml(){try{const xml=exportMusicXml(project.value,score.value);const problems=validateMusicXmlDurations(xml,project.value.beats);if(problems.length){message.value='MusicXML validation failed: '+problems.slice(0,3).join('; ');return;}download(xml,`${project.value.title.replace(/[^a-z0-9-]+/gi,'-')}.musicxml`,'application/vnd.recordare.musicxml+xml');message.value='MusicXML exported; all instrument-measures passed rhythmic validation.';}catch(err){message.value=`Export failed: ${String(err)}`;}}
async function importFile(e:Event){const file=(e.target as HTMLInputElement).files?.[0];if(!file)return;try{if(file.name.endsWith('.tango')){project.value=await loadProject(file);selectedBar.value=0;message.value='Portable project loaded.';}else if(file.name.endsWith('.mid')||file.name.endsWith('.midi')){pending.value=importMidi(await file.arrayBuffer());importMode.value='melody';message.value=`Found ${pending.value.length} MIDI tracks. Choose the melody track.`;}else{const result=importMusicXml(await file.text());pending.value=result.parts;if(result.chords.length&&importMode.value==='melody'){result.chords.forEach((c,i)=>{if(project.value.bars[i])project.value.bars[i].chord=c;});project.value.generatedScore=undefined;}message.value=`Found ${result.parts.length} MusicXML parts. Choose a melody track or import edited score.`;}}catch(err){message.value=`Import failed: ${String(err)}`;}finally{(e.target as HTMLInputElement).value='';}}
function applyImport(){if(!pending.value.length)return;if(importMode.value==='melody'){const notes=pending.value[selectedTrack.value]?.notes??[];const needed=Math.ceil((Math.max(0,...notes.map(n=>n.start+n.duration)))/project.value.beats);while(project.value.bars.length<needed)project.value.bars.push({chord:'',melody:[],section:'A1'});project.value.bars.forEach((b,i)=>b.melody=notes.filter(n=>Math.floor(n.start/project.value.beats)===i).map(n=>({...n,start:n.start-i*project.value.beats})));message.value=`Imported ${notes.length} melody notes. Set chords and sections, then generate.`;}else{project.value.importedScore=transposeScore(scoreFromParts(pending.value),-(project.value.transposeSemitones??0));let count=0;for(const inst of INSTRUMENTS)for(let b=0;b<project.value.bars.length;b++){const old=(project.value.generatedScore?.[inst]??[]).filter(n=>Math.floor(n.start/project.value.beats)===b).map(n=>[n.pitch,n.start,n.duration]);const incoming=(project.value.importedScore[inst]??[]).filter(n=>Math.floor(n.start/project.value.beats)===b).map(n=>[n.pitch,n.start,n.duration]);if(JSON.stringify(old)!==JSON.stringify(incoming)){setProtected(inst,b,true);count++;}}message.value=`Imported edited score; ${count} instrument-measures marked protected. Review before regenerating.`;}pending.value=[];}
let synth:Tone.PolySynth|null=null;async function play(){if(playing.value){Tone.getTransport().stop();Tone.getTransport().cancel();playing.value=false;return;}await Tone.start();synth??=new Tone.PolySynth(Tone.Synth).toDestination();const transport=Tone.getTransport();transport.stop();transport.cancel();transport.bpm.value=project.value.bpm;for(const inst of INSTRUMENTS){if(inst==='Voice')continue;for(const n of score.value[inst]??[]){const seconds=n.start*60/project.value.bpm;transport.schedule(time=>synth?.triggerAttackRelease(Tone.Frequency(n.pitch+(project.value.transposeSemitones??0),'midi'),Math.max(0.08,n.duration*60/project.value.bpm*0.90),time,(n.velocity??80)/127),seconds);}}transport.scheduleOnce(()=>{playing.value=false;transport.stop();},project.value.bars.length*project.value.beats*60/project.value.bpm+0.2);transport.start();playing.value=true;}
const currentNotes=computed(()=>INSTRUMENTS.map(inst=>({inst,notes:(score.value[inst]??[]).filter(n=>Math.floor(n.start/project.value.beats)===selectedBar.value)})));
function addBar(){const previous=project.value.bars.at(-1);project.value.bars.push({chord:previous?.chord??'',melody:[],section:previous?.section??'A1'});selectedBar.value=project.value.bars.length-1;}
function changeSection(e:Event){bar.value.section=(e.target as HTMLSelectElement).value;}
function addArrastre(){const inst:'Piano'='Piano';const b=selectedBar.value,offset=b*project.value.beats;const notes=[...(project.value.generatedScore??generate(project.value))[inst]];const at=offset+Math.min(2,project.value.beats-1);const target=notes.find(n=>n.start>=at)?.pitch??60;notes.push({pitch:target-2,start:at-0.5,duration:0.25,source:'manual'},{pitch:target-1,start:at-0.25,duration:0.25,source:'manual'});project.value.generatedScore={...(project.value.generatedScore??generate(project.value)),[inst]:notes};message.value=`Added a simple notated piano lead-in in measure ${b+1}. This is a prototype gesture, not yet an idiomatic arrastre model.`;}
</script>
<template>
<div class="shell"><header><div class="brand"><span class="logo">𝄞</span><div><strong>Tango Arranger</strong><small>Orquesta típica workbench · prototype 0.8</small></div></div><div class="header-actions"><button class="secondary" @click="newSongOpen=!newSongOpen">+ New blank song</button><button class="secondary" @click="saveProject(project)">↓ Save .tango</button><button class="primary" @click="exportXml">↓ Export MusicXML</button></div></header>
<div class="layout"><aside><div class="eyebrow">PROJECT</div><label>Title<input v-model="project.title"/></label><div class="two"><label>Tempo<input v-model.number="project.bpm" type="number" min="40" max="240"/></label><label>Beats / bar<input v-model.number="project.beats" type="number" min="2" max="4"/></label></div><label>Transpose entire arrangement (semitones)<input type="number" min="-24" max="24" step="1" :value="project.transposeSemitones??0" @change="setTranspose"/><small class="hint">Non-destructive concert-pitch shift: playback, score review, chords and MusicXML change together. Original lead sheet remains intact.</small></label><label>Orchestra profile<select v-model="project.profile"><option v-for="[id,name] in profiles" :key="id" :value="id">{{name}}</option></select></label><label>Overall difficulty<select v-model="project.difficulty"><option v-for="d in difficulties" :key="d" :value="d">{{d}}</option></select></label><button class="secondary" @click="convertMeter" :disabled="project.beats!==2">Convert paired 2/4 bars to 4/4</button><div class="divider"></div><div class="eyebrow">IMPORT & ROUND TRIP</div><label class="file-picker">↑ Import .tango / .musicxml / .mid<input type="file" accept=".tango,.xml,.musicxml,.mid,.midi" @change="importFile" hidden/></label><div v-if="pending.length" class="import-panel"><label>Import as<select v-model="importMode"><option value="melody">Melody only</option><option value="score">Edited full score</option></select></label><label v-if="importMode==='melody'">Track<select v-model.number="selectedTrack"><option v-for="(track,i) in pending" :key="i" :value="i">{{track.name}} ({{track.notes.length}} notes)</option></select></label><button class="primary" @click="applyImport">Apply import</button></div><p class="hint">After editing in MuseScore, export MusicXML and import it here as “Edited full score”. Changed measures will be protected.</p><div class="divider"></div><div class="eyebrow">PLAYBACK</div><button class="play" @click="play">{{playing?'■ Stop':'▶ Play arrangement'}}</button><p class="hint">Basic synthesized playback, not authentic tango instrument sounds.</p></aside>
<main><div v-if="newSongOpen" class="editor" role="region" aria-label="Create blank song">
  <div class="section-heading"><h2>New blank song</h2><button type="button" class="secondary" @click="newSongOpen=false">Cancel</button></div>
  <p class="muted">Start with an empty lead sheet: no demo melody, no chord symbols and no generated accompaniment. Measures are grouped into eight-bar A1 / B1 / A2 / B2 / C sections, where present.</p>
  <div class="two"><label>Song title<input v-model="newSongTitle" placeholder="Untitled Tango"/></label><label>Measures<select v-model.number="newSongMeasures"><option v-for="count in [8,16,24,32,40,48,64]" :key="count" :value="count">{{count}} measures</option></select></label></div>
  <div class="two"><label>Time signature<select v-model.number="newSongBeats"><option :value="4">4/4 — Tango</option><option :value="3">3/4 — Vals</option><option :value="2">2/4 — Milonga / historical notation</option></select></label><label>Tempo (quarter notes/min)<input v-model.number="newSongBpm" type="number" min="40" max="240"/></label></div>
  <div class="overview-actions"><button type="button" class="primary" @click="createBlankSong">Create blank song</button><button type="button" class="secondary" @click="newSongOpen=false">Keep current project</button></div>
  <p class="hint">Creating a new song replaces the current project. You will be asked to confirm before any unsaved work is discarded.</p>
</div><div class="page-title"><div><h1>Arrange your tango</h1><p>From one melody and chords to a complete orchestra score.</p></div><button class="primary" @click="regenerate">↻ Generate orchestra</button></div><nav class="tabs"><button :class="{active:active==='overview'}" @click="active='overview'">1 · Song overview</button><button :class="{active:active==='lead'}" @click="active='lead'">2 · Lead sheet</button><button :class="{active:active==='arrange'}" @click="active='arrange'">3 · Orchestration</button><button :class="{active:active==='score'}" @click="active='score'">4 · Score review</button></nav><div class="notice">{{message}}</div>
<div v-if="chordEditorOpen" class="editor chord-editor" role="region" aria-label="Measure harmony editor">
  <div class="section-heading"><h2>Harmony · measure {{selectedBar+1}}</h2><button class="secondary" type="button" @click="chordEditorOpen=false">Close</button></div>
  <p class="muted">Chords belong to the measure and apply to all instruments. Leave the field empty to clear the harmony. Commas divide the measure into slots: in 4/4, <code>D,G</code> changes to G on beat 3; <code>D,D,D,G</code> changes on beat 4. Repeated symbols hold the chord.</p>
  <div class="two"><label>Chord sequence<input v-model="chordDraft" spellcheck="false" @keydown.enter.prevent="applyChordEditor" placeholder="D,D,D,G"/></label><label>Beat-by-beat preview<div class="chord-beat-preview">{{chordBeatLabels(chordDraft)}}</div></label></div>
  <div class="overview-actions"><button class="primary" @click="applyChordEditor">Apply harmony</button><button class="secondary" @click="chordEditorOpen=false">Cancel</button></div>
</div>
<section v-if="active==='overview'" class="overview-section"><div class="section-heading"><h2>Song orchestration map</h2><span>{{project.bars.length}} measures · {{INSTRUMENTS.length}} parts</span></div><p class="muted">Scan roles and playing techniques across the whole piece. Click a measure heading to edit its chords; click an instrument heading to open the chord editor for the selected measure. Click a cell to edit one instrument-measure, or use the range editor to apply a role, articulation or violin chord technique to multiple measures. Empty overrides inherit section defaults and generated articulation cycles.</p>
<div class="overview-legend"><span><i class="legend-dot melody"></i> Melody</span><span><i class="legend-dot chords"></i> Chords / arpeggio / pizzicato</span><span><i class="legend-dot harmony"></i> Harmony</span><span><i class="legend-dot bass"></i> Bass</span><span><i class="legend-dot rest"></i> Rest</span><span><i class="legend-dot overridden"></i> Manual override (corner)</span></div>
<div class="song-map-scroll"><table class="song-map"><thead><tr><th class="sticky-instrument">Instrument</th><th v-for="(b,i) in project.bars" :key="i" :class="{'section-break':i===0||b.section!==project.bars[i-1].section}"><button type="button" class="measure-chord-heading" :title="`Edit chords in measure ${i+1}`" @click="openChordEditor(i)"><small>{{b.section}}</small><strong>{{i+1}}</strong><small>{{b.chord}}</small></button></th></tr></thead><tbody><tr v-for="inst in overviewInstruments" :key="inst"><th class="sticky-instrument"><button type="button" class="instrument-heading-button" :title="`Edit chords in selected measure for ${inst}`" @click="overviewInstrument=inst;openChordEditor(overviewFocus)">{{inst}} <span aria-hidden="true">♫</span></button></th><td v-for="(b,i) in project.bars" :key="i" :class="{'section-break':i===0||b.section!==project.bars[i-1].section}"><button type="button" :class="['song-cell',`song-role-${effectiveRole(inst,i)}`,{focused:overviewFocus===i&&overviewInstrument===inst,modified:roleOverridden(inst,i)||articulationOverride(inst,i)!=='auto'||Boolean(project.measureViolinTechniques?.[`${inst}:${i}`])}]" :title="`${inst} · m${i+1} · ${effectiveRole(inst,i)} · ${cellArticulation(inst,i)}`" @click="focusOverview(inst,i)"><span class="cell-role">{{cellLabel(inst,i)}}</span><small>{{cellArticulation(inst,i)}}</small></button></td></tr></tbody></table></div>
<div class="editor overview-edit"><h3>Edit instrument measures</h3><div class="overview-controls"><label>Instrument<select v-model="overviewInstrument"><option v-for="inst in INSTRUMENTS" :key="inst" :value="inst">{{inst}}</option></select></label><label>From measure<input v-model.number="overviewStart" type="number" min="1" :max="project.bars.length"/></label><label>To measure<input v-model.number="overviewEnd" type="number" :min="overviewStart" :max="project.bars.length"/></label><label>Musical role<select v-model="overviewRole"><option value="inherit">Inherit section</option><option v-for="role in roles" :key="role" :value="role">{{role}}</option></select></label><label v-if="overviewInstrument.startsWith('Violin')||overviewInstrument.startsWith('Bandoneon')">Articulation<select v-model="overviewArt"><option v-for="mode in articulationModes" :key="mode" :value="mode">{{mode==='auto'?'Inherit default':mode==='legato'?(overviewInstrument.startsWith('Violin')?'Arco / legato':'Legato'):mode.replaceAll('_',' ')}}</option></select></label><label v-if="overviewInstrument.startsWith('Violin')">Chord technique<select v-model="overviewTechnique"><option value="inherit">Inherit section</option><option v-for="tech in violinTechniques" :key="tech" :value="tech">{{tech.replaceAll('_',' ')}}</option></select></label></div><div class="overview-actions"><button class="primary" @click="applyOverviewRange">Apply to range</button><button class="secondary" @click="applyOverviewSection">Apply to current section ({{chosenSection}})</button><button class="secondary" @click="overviewStart=1;overviewEnd=project.bars.length">Select whole song</button><button class="secondary" @click="regenerate">↻ Regenerate / merge protected edits</button></div><p class="hint" role="status">{{overviewNotice||'Choose a cell to load its overrides. Inherit restores the section or automatic default. The range editor changes only the selected instrument.'}}</p><p class="hint">Tip: for a violin playing chords, choose the Chords role and then select pizzicato, pizzicato arpeggio, arpeggio, double stop, sustained or block. Arco and staccato articulation are separate from the harmonic role.</p></div>
</section>
<section v-else-if="active==='lead'"><div class="section-heading"><h2>Melody & harmony</h2><span>{{project.bars.length}} measures</span></div><p class="muted">Select a measure and edit its chord sequence, section and melody. Click the chord tile or the chord field to open the shared harmony editor. Notes use <code>D5:1@0</code> (pitch:duration@beat), separated by spaces. Durations and beats are in quarter-note units.</p><div class="bar-grid"><button v-for="(b,i) in project.bars" :key="i" :class="['bar-tile',{selected:selectedBar===i}]" @click="openChordEditor(i)"><small>{{i+1}} · {{b.section}}</small><strong>{{b.chord}}</strong><span>{{b.melody.length}} notes</span></button></div><button class="secondary" @click="addBar">+ Add measure</button><div class="editor"><h3>Measure {{selectedBar+1}}</h3><div class="two"><label>Chords in measure <button class="secondary chord-edit-button" type="button" @click="openChordEditor(selectedBar)">{{bar.chord||'No chord'}} · Edit chords</button></label><label>Section<select :value="bar.section" @change="changeSection"><option v-for="s in ['A1','B1','A2','B2','C']" :key="s">{{s}}</option></select></label></div><label>Melody notes<textarea v-model="melodyText" rows="3" spellcheck="false"/></label><button class="primary" @click="setMelody">Apply melody notes</button><p class="hint">The hybrid staff/piano-roll editor is planned; this functional first version uses compact note entry and MIDI/MusicXML import.</p></div></section>
<section v-else-if="active==='arrange'"><div class="section-heading"><h2>Orchestration roles</h2><span>Phrase-level presets</span></div><div class="section-tabs"><button v-for="s in sections" :key="s" :class="{selected:chosenSection===s}" @click="chosenSection=s">{{s}}</button></div><div class="role-list"><div v-for="inst in INSTRUMENTS" :key="inst" class="role-row"><span>{{inst}}</span><select :value="project.roles[chosenSection]?.[inst]??'rest'" @change="setRole(inst,$event)"><option v-for="role in roles" :key="role" :value="role">{{role}}</option></select></div></div><div class="editor"><h3>Violin chord techniques</h3><p class="muted">Used when the violin's role is chords. Double stops are restricted to reachable adjacent strings in low positions; if none exists, an arpeggio is used.</p><div class="role-list"><div v-for="inst in (['Violin I','Violin II'] as const)" :key="inst" class="role-row"><span>{{inst}}</span><select :value="violinSetting(inst)" @change="setViolinSetting(inst,$event)"><option v-for="tech in violinTechniques" :key="tech" :value="tech">{{tech.replaceAll('_',' ')}}</option></select></div></div></div><div class="editor"><h3>Bandoneon following</h3><p class="muted">Choose a source and how to follow it for this section. Following overrides the bandoneon's role when the source has notes.</p><div v-for="inst in (['Bandoneon I','Bandoneon II'] as const)" :key="inst" class="two"><label>{{inst}} follows<select :value="followSetting(inst).target" @change="setFollow(inst,'target',$event)"><option v-for="target in followTargets" :key="target" :value="target">{{target}}</option></select></label><label>Method<select :value="followSetting(inst).method" @change="setFollow(inst,'method',$event)"><option v-for="method in followMethods" :key="method" :value="method">{{method}}</option></select></label></div></div><div class="editor"><h3>Instrument difficulty and activity</h3><p class="muted">Activity is a deterministic target for measures containing musical material, not beats sounded. Explicit Rest roles remain silent. The level limits technical complexity without automatically making the part sparse.</p><div class="role-list"><div v-for="inst in INSTRUMENTS.filter(i=>i!=='Voice')" :key="inst" class="role-row"><span>{{inst}}</span><select :value="instrumentDifficulty(inst)" @change="setInstrumentDifficulty(inst,$event)"><option v-for="d in difficulties" :key="d" :value="d">{{d}}</option></select><label class="hint">Activity <input type="number" min="0" max="100" step="5" :value="instrumentTarget(inst)" @change="setInstrumentTarget(inst,$event)"/> %</label><label class="hint">Dynamics offset <input type="number" min="-25" max="25" step="5" :value="instrumentDynamicsOffset(inst)" @change="setInstrumentDynamicsOffset(inst,$event)"/></label></div></div></div><div class="editor"><h3>Dynamics and phrase expression</h3><label><input type="checkbox" :checked="project.expression?.enabled??true" @change="toggleExpression('enabled',$event)"/> Export dynamics and scale generated velocities</label><label>Dynamic at start of {{chosenSection}}<select :value="sectionDynamic()" @change="setSectionDynamic"><option v-for="d in dynamicMarks" :key="d" :value="d">{{d}}</option></select></label><label><input type="checkbox" :checked="project.expression?.crescendo??true" @change="toggleExpression('crescendo',$event)"/> Add section crescendos</label></div><div class="editor"><h3>Eight-bar articulation and measure overrides</h3><p class="muted">Default: approximately eight measures marcato/staccato alternating with lyrical legato (arco for bowed violin). Bandoneon legato describes connected phrasing, not bowing. Violin II and Bandoneon II switches are staggered for variation.</p><label><input type="checkbox" :checked="project.articulation?.enabled??true" @change="project.articulation??=defaultArticulation();project.articulation.enabled=($event.target as HTMLInputElement).checked"/> Generate articulation cycles</label><label>Measures per phase<input type="number" min="1" max="32" :value="project.articulation?.phraseBars??8" @change="project.articulation??=defaultArticulation();project.articulation.phraseBars=Math.max(1,Math.min(32,Number(($event.target as HTMLInputElement).value)||8))"/></label><label>Override measure<select v-model.number="selectedBar"><option v-for="(b,i) in project.bars" :key="i" :value="i">{{i+1}} · {{b.section}}</option></select></label><div class="role-list"><div v-for="inst in INSTRUMENTS.filter(i=>i.startsWith('Violin')||i.startsWith('Bandoneon'))" :key="inst" class="role-row"><span>{{inst}}</span><select :value="barArticulation(inst)" @change="setBarArticulation(inst,$event)"><option v-for="art in articulationModes" :key="art" :value="art">{{art.replaceAll('_',' ')}}</option></select><small class="hint">{{inferredArticulation(inst)}}</small></div></div><p class="hint">Press Generate orchestra after changing articulation. An explicit override takes precedence over the default cycle.</p></div><div class="editor"><h3>Tango gestures</h3><p class="muted">First experimental gesture: insert a two-note piano approach before beat 3 of the selected measure.</p><div class="two"><label>Target measure<select v-model.number="selectedBar"><option v-for="(b,i) in project.bars" :key="i" :value="i">{{i+1}} · {{b.chord}}</option></select></label><div class="align-bottom"><button class="secondary" @click="addArrastre">+ Simple arrastre lead-in</button></div></div><p class="hint">Profiles model selected accompaniment, accent and expression tendencies; these are configurable heuristics, not transcriptions of any specific recording.</p></div></section>
<section v-else><div class="section-heading"><h2>Generated score review</h2><span>{{scoreStats(score)}} notes · {{INSTRUMENTS.length}} parts</span></div><p class="muted">Review instrument-measures, protect edits imported from MuseScore, and regenerate selectively. This is a note-event overview, not an engraved staff score.</p><div class="two"><label>Measure<select v-model.number="selectedBar"><option v-for="(b,i) in project.bars" :key="i" :value="i">{{i+1}} · {{b.section}} · {{b.chord}}</option></select></label><div class="align-bottom"><button class="secondary" @click="exportXml">Export score to MuseScore ↗</button></div></div><div class="score-rows"><div v-for="entry in currentNotes" :key="entry.inst" class="score-row"><div class="score-name"><strong>{{entry.inst}}</strong><small class="muted">{{activitySummary(entry.inst)}}% measures active</small><label class="protect"><input type="checkbox" :checked="!!project.protectedBars[`${entry.inst}:${selectedBar}`]" @change="setProtected(entry.inst,selectedBar,($event.target as HTMLInputElement).checked)"/> Protect</label></div><div class="notes"><span v-for="(n,i) in entry.notes" :key="i" class="note-chip">{{midiName(n.pitch+(project.transposeSemitones??0))}} <small>{{n.duration}} beat</small></span><span v-if="!entry.notes.length" class="muted">Rest</span></div></div></div></section>
</main></div><footer>Local-first prototype · Your project stays in your browser unless you export it · MusicXML for MuseScore</footer></div>
</template>
